INSERT OR IGNORE INTO academy_knowledge (id, kind, category, title_pl, title_en, content_pl, content_en, tags, source_ref) VALUES
('beginner:ZERO-141','beginner','Sieć i internet / Network','Internet działa, jedna strona nie','','description: Przyczyną może być sama witryna, przeglądarka lub konfiguracja sieci. step: Porównaj inną stronę i drugą przeglądarkę, nie ignorując ostrzeżeń.','','',''),
('beginner:ZERO-142','beginner','System i sterowniki / System & Drivers','Przeglądarka działa wolno','','description: Rozszerzenia, liczba kart i obciążenie systemu wpływają na płynność. step: Porównaj działanie z mniejszą liczbą otwartych kart.','','',''),
('beginner:ZERO-143','beginner','System i sterowniki / System & Drivers','Podejrzane rozszerzenie przeglądarki','','description: Nieznane dodatki mogą zmieniać wyniki wyszukiwania lub zachowanie stron. step: Przejrzyj listę rozszerzeń i korzystaj z ustawień oficjalnej przeglądarki.','','',''),
('beginner:ZERO-144','beginner','System i sterowniki / System & Drivers','Menedżer zadań i obciążenie','','description: Wysokie użycie procesora lub dysku pomaga wskazać obszar problemu. step: Zanotuj nazwę procesu i sprawdź, czy trwa aktualizacja.','','',''),
('beginner:ZERO-145','beginner','Serwis i diagnostyka / Service & Diagnostics','Wolne miejsce w chmurze','','description: Synchronizacja może zatrzymać się po osiągnięciu limitu miejsca. step: Sprawdź komunikat usługi i kopię plików przed ich usuwaniem.','','',''),
('beginner:ZERO-146','beginner','Dyski i dane / Storage & Data','Pliki nie synchronizują się','','description: Problem może dotyczyć połączenia, konfliktów nazw lub limitu przestrzeni. step: Sprawdź status aplikacji synchronizującej i kopię lokalnych plików.','','',''),
('beginner:ZERO-147','beginner','Dyski i dane / Storage & Data','Przypadkowo usunięty plik','','description: Dalszy zapis na tym samym nośniku może ograniczyć szanse odzyskania. step: Sprawdź kosz i istniejące kopie; przy ważnych danych ogranicz użycie dysku.','','',''),
('beginner:ZERO-148','beginner','Dyski i dane / Storage & Data','Uszkodzone archiwum','','description: Błąd rozpakowania może wynikać z niepełnego pobrania albo awarii nośnika. step: Sprawdź oryginalne źródło i stan kopii, nie nadpisując jedynego archiwum.','','',''),
('beginner:ZERO-149','beginner','Dyski i dane / Storage & Data','Sprawdzenie plików po przeniesieniu','','description: Sam komunikat o zakończeniu kopiowania nie potwierdza czytelności danych. step: Otwórz kilka skopiowanych plików przed usunięciem oryginałów.','','',''),
('beginner:ZERO-150','beginner','Bezpieczeństwo i organizacja / Safety & Workflow','Bezpieczne odłączanie nośnika','','description: Odłączenie podczas zapisu może spowodować utratę części danych. step: Zakończ operacje i użyj funkcji bezpiecznego wysuwania.','','',''),
('beginner:ZERO-151','beginner','Serwis i diagnostyka / Service & Diagnostics','Stary komputer przed oddaniem','','description: Na dysku mogą pozostać prywatne pliki i aktywne sesje. step: Zrób kopię danych i zapoznaj się z zalecaną procedurą wymazania dla urządzenia.','','',''),
('beginner:ZERO-152','beginner','Dyski i dane / Storage & Data','Wymiana dysku przed serwisem','','description: Zmiana nośnika może wpływać na gwarancję oraz dostęp do danych. step: Sprawdź zasady producenta i zachowaj kopię oraz klucz odzyskiwania.','','',''),
('beginner:ZERO-153','beginner','Bezpieczeństwo i organizacja / Safety & Workflow','Koszt naprawy a wymiana sprzętu','','description: Cena części, robocizna i wiek urządzenia wpływają na decyzję. step: Poproś serwis o wycenę i zakres prac przed wyrażeniem zgody.','','',''),
('beginner:ZERO-154','beginner','Bezpieczeństwo i organizacja / Safety & Workflow','Dokumentowanie wykonanych testów','','description: Zapis działań pomaga uniknąć powtarzania ryzykownych prób. step: Przygotuj krótką listę objawów, dat i wyników bez podawania haseł.','','',''),
('beginner:ZERO-155','beginner','Bezpieczeństwo i organizacja / Safety & Workflow','Plan bezpiecznej diagnozy','','description: Dobra diagnoza zaczyna się od objawu, kopii danych i prostych porównań. step: Wybierz jedną bezpieczną, odwracalną czynność i zanotuj wynik.','','',''),
('beginner:ZERO-156','beginner','Serwis i diagnostyka / Service & Diagnostics','Czyszczenie gniazd i styków','','description: Kurz lub nalot może zakłócać kontakt, ale niewłaściwe czyszczenie łatwo uszkadza delikatne elementy. step: Odłącz sprzęt i użyj wyłącznie metody opisanej w instrukcji producenta.','','',''),
('beginner:ZERO-157','beginner','Serwis i diagnostyka / Service & Diagnostics','Test obciążeniowy','','description: Test obciążeniowy może ujawnić problem pojawiający się dopiero pod większym obciążeniem. step: Najpierw zabezpiecz dane i obserwuj temperatury; przerwij test przy nietypowym zapachu lub wyłączaniu.','','',''),
('beginner:ZERO-158','beginner','System i sterowniki / System & Drivers','Sterownik chipsetu','','description: Sterownik chipsetu wpływa na komunikację między procesorem, pamięcią i urządzeniami. step: Sprawdź model płyty oraz wersję sterownika na oficjalnej stronie producenta.','','',''),
('beginner:ZERO-159','beginner','Dyski i dane / Storage & Data','Konfiguracja wielu dysków','','description: Kilka dysków zwiększa możliwości, ale komplikuje wybór nośnika i kopie zapasowe. step: Zidentyfikuj każdy dysk przed zmianą kolejności rozruchu lub partycji.','','',''),
('beginner:ZERO-160','beginner','Bezpieczeństwo i organizacja / Safety & Workflow','Praca w rękawiczkach i ochrona dłoni','','description: Rękawiczki nie zastępują odłączenia zasilania ani ochrony przed ESD. step: Pracuj spokojnie, zdejmij biżuterię i nie dotykaj styków palcami.','','',''),
('beginner:ZERO-161','beginner','Bezpieczeństwo i organizacja / Safety & Workflow','Przygotowanie stanowiska pracy','','description: Porządek, dobre światło i oznaczone śrubki zmniejszają ryzyko pomyłek podczas naprawy. step: Przygotuj czyste stanowisko, pojemnik na śrubki i instrukcję dokładnego modelu.','','',''),
('beginner:ZERO-162','beginner','Sprzęt i podzespoły / Hardware','Identyfikacja podzespołów','','description: Podobne elementy mogą różnić się złączem, generacją i przeznaczeniem. step: Zapisz oznaczenia części i porównaj je z dokumentacją producenta przed demontażem.','','',''),
('beginner:ZERO-163','beginner','Zasilanie / Power','Kontrola połączeń zasilania','','description: Luźna wtyczka może powodować niestabilność, ale wciskanie jej na siłę może uszkodzić gniazdo. step: Odłącz zasilanie i sprawdź zgodność oraz kierunek wtyczki bez używania nadmiernej siły.','','',''),
('beginner:ZERO-164','beginner','Bezpieczeństwo i organizacja / Safety & Workflow','Bezpieczne przenoszenie komputera','','description: Wstrząsy i nacisk na ekran lub porty mogą pogorszyć istniejącą usterkę. step: Zamknij system, odłącz przewody i przenoś urządzenie za stabilną część obudowy.','','',''),
('beginner:ZERO-165','beginner','Bezpieczeństwo i organizacja / Safety & Workflow','Lista części przed zakupem','','description: Niekompatybilna część może nie rozwiązać problemu i utrudnić zwrot. step: Zapisz model, rewizję i wymagania podzespołu, a następnie sprawdź je w kilku źródłach.','','',''),
('beginner:ZERO-166','beginner','Peryferia / Peripherals','Zasilanie USB i szybkie ładowanie','','description: Różne standardy USB mogą oferować inne napięcie, moc i sposób negocjacji ładowania. step: Sprawdź oznaczenia ładowarki, przewodu i urządzenia; nie używaj uszkodzonych akcesoriów.','','',''),
('beginner:ZERO-167','beginner','Dyski i dane / Storage & Data','Pamięć masowa w laptopie','','description: Wymiana nośnika zależy od formatu, interfejsu, miejsca i obsługi przez konkretny model. step: Zapisz kopię danych i sprawdź instrukcję serwisową przed zakupem części.','','',''),
('beginner:ZERO-168','beginner','Obraz i ekran / Display','Brak obrazu po aktualizacji sterownika','','description: Zmiana sterownika może wpłynąć na wybór wyjścia obrazu lub zgodność z monitorem. step: Uruchom system w bezpieczny sposób i zapisz poprzednią wersję przed kolejną zmianą.','','',''),
('beginner:ZERO-169','beginner','Chłodzenie / Cooling','Wentylacja laptopa na miękkiej powierzchni','','description: Koc lub poduszka może zasłonić wloty i zwiększyć temperaturę urządzenia. step: Przenieś laptop na twardą, stabilną powierzchnię i obserwuj temperaturę podczas pracy.','','',''),
('beginner:ZERO-170','beginner','Bezpieczeństwo i organizacja / Safety & Workflow','Przygotowanie nośnika do wymiany','','description: Nieprawidłowe przygotowanie może spowodować utratę systemu lub danych. step: Sprawdź kopię zapasową, klucz odzyskiwania i zgodność nowego nośnika przed demontażem.','','',''),
('beginner:ZERO26-001','beginner','Sieć i łączność','Wi-Fi 7 i funkcja MLO','','description: Wi-Fi 7 może korzystać z wielu łączy, ale wymaga zgodnego routera, adaptera i sterownika. step: Zapisz model karty i routera, potem sprawdź pasma i zgodność MLO.','','',''),
('beginner:ZERO26-002','beginner','Sieć i łączność','Kanał Wi-Fi 320 MHz','','description: Szeroki kanał nie jest dostępny w każdej lokalizacji ani na każdym urządzeniu. step: Sprawdź regionalne ograniczenia, kanał routera i parametry karty.','','',''),
('beginner:ZERO26-003','beginner','Sieć i łączność','Intel Wi-Fi 7 BE200 — zgodność','','description: Moduł M.2 wymaga zgodności slotu, anten i firmware laptopa. step: Sprawdź listę zatwierdzonych adapterów OEM przed zakupem.','','',''),
('beginner:ZERO26-004','beginner','Porty i złącza','USB4 Version 2.0','','description: USB4 v2.0 to nowa wersja specyfikacji, ale porty urządzeń różnią się możliwościami. step: Porównaj dokumentację hosta, docka i kabla.','','',''),
('beginner:ZERO26-005','beginner','Porty i złącza','Thunderbolt 5 — 80/120 Gb/s','','description: Thunderbolt 5 oferuje wysoką przepustowość zależną od trybu i podłączonych urządzeń. step: Sprawdź oznaczenia hosta, kabla i docka.','','','');
